<script lang="ts">
  import { onMount } from 'svelte';
  import { cars, photo, eur, number } from './data';
  let { variant, id }: { variant: 'atelier' | 'horizonte'; id?: string } = $props();
  const base = $derived(`/stand-${variant}`);
  const car = $derived(cars.find(c => c.id === id));
  let filter = $state('Todas');
  let search = $state('');
  let sort = $state('selection');
  let menu = $state(false);
  let contact = $state(false);
  let sent = $state(false);
  let gallery = $state(false);
  let angle = $state(0);
  let scroll = $state(0);
  let reduced = $state(false);
  const filtered = $derived(cars.filter(c => (filter === 'Todas' || c.category === filter || c.fuel === filter) && `${c.brand} ${c.model}`.toLowerCase().includes(search.toLowerCase())).toSorted((a,b) => sort === 'price' ? a.price - b.price : sort === 'year' ? b.year - a.year : 0));
  $effect(() => { id; angle = 0; gallery = false; menu = false; });
  onMount(() => { reduced = matchMedia('(prefers-reduced-motion: reduce)').matches; });
  function reveal(node: HTMLElement) {
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    node.classList.add('pending');
    const observer = new IntersectionObserver(entries => { entries.forEach(entry => { if(entry.isIntersecting) { node.classList.remove('pending'); observer.unobserve(node); } }); }, { threshold: 0.08 });
    observer.observe(node);
    return { destroy() { observer.disconnect(); } };
  }
  function openContact() { sent = false; contact = true; }
</script>

<svelte:window bind:scrollY={scroll} onkeydown={(e) => { if(e.key === 'Escape') { gallery = false; contact = false; menu = false; } }} />
<svelte:head><title>{car ? `${car.brand} ${car.model}` : variant === 'atelier' ? 'O próximo capítulo começa aqui' : 'Há caminhos que merecem outro carro'} · Auto Nunes Martins</title><meta name="description" content="Duas perspetivas sobre a próxima viagem. Descubra a seleção Auto Nunes Martins." /></svelte:head>

<div class="concept {variant}">
  <div class="preview">ESTUDO VISUAL <span>Dados e imagens ilustrativos</span><a href={variant === 'atelier' ? '/stand-horizonte' : '/stand-atelier'}>Ver {variant === 'atelier' ? 'Horizonte' : 'Atelier'} ↗</a></div>
  <header class:scrolled={scroll > 50}>
    <a class="wordmark" href={base} aria-label="Auto Nunes Martins — início"><span class="brand-mark">nm<span>↗</span></span><span>AUTO<br/><b>NUNES MARTINS</b></span></a>
    <nav class:expanded={menu} aria-label="Navegação principal"><a href={`${base}#colecao`}>As nossas viaturas</a><a href={`${base}#filosofia`}>A nossa forma de estar</a><button onclick={openContact}>Vamos conversar <span>↗</span></button></nav>
    <button class="menu" onclick={() => menu = !menu} aria-label="Abrir navegação" aria-expanded={menu}>{menu ? 'Fechar' : 'Menu'} ☰</button>
  </header>

  {#if id && !car}
    <section class="missing"><p>Este caminho não tem uma viatura.</p><h1>Vamos voltar<br/>à seleção?</h1><a class="button" href={base}>Ver viaturas ↗</a></section>
  {:else if car}
    <main class="detail">
      <div class="breadcrumb"><a href={`${base}#colecao`}>← Todas as viaturas</a><span>{car.brand} / {car.model}</span></div>
      <section class="detail-intro" use:reveal><div><p class="eyebrow">A NOSSA SELEÇÃO / {car.year}</p><h1>{car.brand}<br/><em>{car.model}.</em></h1><p>{car.line}</p></div><div class="price-block"><small>O seu próximo capítulo</small><strong>{eur(car.price)}</strong><button class="button" onclick={openContact}>Quero conhecer esta viatura ↗</button></div></section>
      <div class="detail-image"><img src={photo(car.image, 2000)} alt={`${car.brand} ${car.model} — fotografia ilustrativa`} style={`object-position:${angle === 1 ? '25% 50%' : angle === 2 ? '75% 50%' : '50% 50%'};transform:scale(${angle ? 1.35 : 1})`} /><span class="image-note">Fotografia ilustrativa</span><button class="gallery-button" onclick={() => gallery = true}>⤢ Ampliar fotografia</button></div>
      <div class="image-tools"><span>Um olhar mais próximo.</span><div>{#each ['Completa', 'Pormenor esquerdo', 'Pormenor direito'] as label, i}<button class:chosen={angle === i} onclick={() => angle = i}>{label}</button>{/each}</div></div>
      <section class="specs" use:reveal>{#each [['Ano', String(car.year)], ['Quilómetros', `${number(car.km)} km`], ['Combustível', car.fuel], ['Caixa', 'Automática'], ['Potência', `${car.power} cv`]] as spec}<div><small>{spec[0]}</small><strong>{spec[1]}</strong></div>{/each}</section>
      <section class="detail-story" use:reveal><div><p class="eyebrow">PARA OS DIAS QUE VÊM</p><h2>Mais do que chegar.<br/><em>Gostar do caminho.</em></h2><p>Há escolhas que fazem parte de quem somos. Esta é uma viatura para quem valoriza o prazer de conduzir, os detalhes bem resolvidos e a liberdade de decidir o próximo destino.</p><p>Conheça-a ao seu ritmo. Estamos disponíveis para apresentar todos os detalhes e ajudar a encontrar a escolha certa para si.</p></div><div class="equipment"><h3>O essencial, à vista.</h3>{#each [['Conforto & interior', 'Climatização automática, volante multifunções e acabamentos de qualidade.'], ['Tecnologia & ligação', 'Sistema de navegação, conectividade Bluetooth e sensores de estacionamento.'], ['Sobre esta apresentação', 'Especificações, equipamento, preços e fotografias são exemplos para avaliação visual. Não constituem uma oferta comercial.']] as item}<details><summary>{item[0]} <span>+</span></summary><p>{item[1]}</p></details>{/each}</div></section>
      <section class="related"><div class="section-heading"><div><p class="eyebrow">CONTINUE A DESCOBRIR</p><h2>Outros caminhos.</h2></div><a href={`${base}#colecao`}>Ver toda a seleção ↗</a></div><div class="cards related-cards">{#each cars.filter(c => c.id !== id).slice(0, 3) as vehicle}<a class="car-card" href={`${base}/${vehicle.id}`}><div class="car-photo"><img loading="lazy" src={photo(vehicle.image, 900)} alt={`${vehicle.brand} ${vehicle.model}`} /><span>↗</span></div><div class="car-heading"><h3>{vehicle.brand} <b>{vehicle.model}</b></h3><strong>{eur(vehicle.price)}</strong></div><p class="car-meta">{vehicle.year} <i>·</i> {number(vehicle.km)} km <i>·</i> {vehicle.fuel}</p></a>{/each}</div></section>
    </main>
  {:else}
    <main>
      <section class="hero">
        <div class="hero-copy"><p class="eyebrow"><span class="dot"></span> AUTO NUNES MARTINS · SELEÇÃO AUTOMÓVEL</p><h1>{#if variant === 'atelier'}O próximo<br/>capítulo.<br/><em>O seu carro.</em>{:else}Há caminhos<br/>que merecem<br/><em>outro carro.</em>{/if}</h1><p class="hero-description">Para a rotina. Para o inesperado.<br/>Para tudo o que ainda está por viver.</p><a class="button" href="#colecao">Encontre o seu próximo carro <span>↗</span></a><div class="hero-foot"><span>Escolhidos com critério.<br/>Apresentados com transparência.</span><a href="#colecao" aria-label="Descer para as viaturas">↓</a></div></div>
        <div class="hero-visual"><img src={photo('photo-1503376780353-7e6692767b70', 2000)} alt="Porsche numa estrada rodeada de natureza" style={`transform:translateY(${reduced ? 0 : Math.min(scroll * .13, 100)}px) scale(1.13)`} /><div class="visual-top"><span>01 / EM DESTAQUE</span><span>UMA NOVA PERSPETIVA</span></div><a class="hero-caption" href={`${base}/porsche-911`}><div><small>A ARTE DE CONDUZIR</small><h2>Porsche 911 Carrera</h2><p>2021 · Automática · 18 900 km</p></div><span>↗</span></a></div>
        <div class="hero-index">{variant === 'atelier' ? 'ATELIER — 01' : 'HORIZONTE — 02'}</div>
      </section>
      <div class="values-strip"><span>O carro certo.</span><span>Uma escolha informada.</span><span>Uma conversa de cada vez.</span><span>O caminho é seu. ↗</span></div>
      <section class="collection" id="colecao">
        <div class="section-heading" use:reveal><div><p class="eyebrow">ESCOLHAS COM PERSONALIDADE</p><h2>Encontre a sua<br/><em>próxima direção.</em></h2></div><p>Uma seleção para diferentes formas de viver.<br/>Descubra o que faz sentido para si.</p></div>
        <div class="filterbar"><div class="filters">{#each ['Todas', 'Familiar', 'Berlina', 'Desportivo', 'Elétrico'] as item}<button class:active={filter === item} onclick={() => filter = item}>{item}</button>{/each}</div><div class="search-sort"><input aria-label="Pesquisar viaturas" placeholder="Pesquisar marca ou modelo" bind:value={search}/><select aria-label="Ordenar viaturas" bind:value={sort}><option value="selection">A nossa seleção</option><option value="price">Preço mais baixo</option><option value="year">Mais recentes</option></select></div></div>
        <p class="results" aria-live="polite">{filtered.length.toString().padStart(2, '0')} VIATURAS PARA DESCOBRIR</p>
        <div class="cards">{#each filtered as vehicle, i (vehicle.id)}<a class="car-card" href={`${base}/${vehicle.id}`} use:reveal><div class="car-photo"><img loading="lazy" src={photo(vehicle.image, 1100)} alt={`${vehicle.brand} ${vehicle.model} — imagem ilustrativa`} /><div class="car-label">{vehicle.category}</div><span>↗</span></div><div class="car-heading"><h3>{vehicle.brand} <b>{vehicle.model}</b></h3><strong>{eur(vehicle.price)}</strong></div><p class="car-meta">{vehicle.year} <i>·</i> {number(vehicle.km)} km <i>·</i> {vehicle.fuel}</p><div class="card-bottom"><small>{vehicle.line.split(' · ')[0]}</small><span>Conhecer viatura ↗</span></div></a>{/each}</div>
        {#if !filtered.length}<div class="empty"><h3>Vamos explorar outro caminho?</h3><p>Não encontrámos viaturas com esta pesquisa.</p><button class="button" onclick={() => { filter = 'Todas'; search = ''; }}>Limpar filtros</button></div>{/if}
      </section>
      <section class="philosophy" id="filosofia"><div class="philosophy-image"><img loading="lazy" src={photo('photo-1440404653325-ab127d49abc1', 1400)} alt="Estrada que atravessa uma paisagem natural"/><span>O MELHOR DESTINO É O QUE ESCOLHE.</span></div><div class="philosophy-copy" use:reveal><p class="eyebrow">A NOSSA FORMA DE ESTAR</p><h2>Um carro é pessoal.<br/><em>A escolha também.</em></h2><p>Não há dois condutores iguais. Por isso, começamos por ouvir: os seus dias, os seus planos, aquilo que procura no próximo carro.</p><p>Depois, tratamos de tornar a escolha mais simples. Com informação clara, atenção ao detalhe e espaço para decidir.</p><a href="#contacto">Conheça-nos numa conversa <span>↗</span></a><div class="principles"><div><small>01</small><h3>Ouvir primeiro.</h3></div><div><small>02</small><h3>Mostrar tudo.</h3></div><div><small>03</small><h3>Escolher bem.</h3></div></div></div></section>
      <section class="steps" use:reveal><p class="eyebrow">SIMPLES, DO PRIMEIRO OLÁ À PRÓXIMA VIAGEM</p><div>{#each [['01', 'Descubra.', 'Explore a seleção e guarde uma ideia do que procura.'], ['02', 'Conheça.', 'Veja os detalhes e combine uma visita ao seu ritmo.'], ['03', 'Parta.', 'Encontre a viatura que faz sentido na sua vida.']] as item}<article><small>{item[0]} /</small><h3>{item[1]}</h3><p>{item[2]}</p></article>{/each}</div></section>
    </main>
  {/if}

  <section class="contact-section" id="contacto" use:reveal><p class="eyebrow">A PRÓXIMA VIAGEM COMEÇA NUMA CONVERSA</p><div><h2>Qual é o seu<br/><em>próximo destino?</em></h2><button onclick={openContact} aria-label="Abrir pedido de contacto">↗</button></div><p>Estamos por aqui. Conte-nos o que procura.</p></section>
  <footer><a class="footer-brand" href={base}>auto nunes martins<span>O caminho é seu.</span></a><div><a href={`${base}#colecao`}>Viaturas</a><a href={`${base}#filosofia`}>Sobre nós</a><button onclick={openContact}>Contacto</button></div><div class="footer-bottom"><span>© {new Date().getFullYear()} Auto Nunes Martins</span><span>Conceito {variant === 'atelier' ? 'Atelier' : 'Horizonte'} · Demonstração visual</span><a href="#top" onclick={() => window.scrollTo({ top: 0, behavior: reduced ? 'instant' : 'smooth' })}>Voltar ao início ↑</a></div></footer>

  {#if contact}<div class="modal-backdrop" role="presentation"><section role="dialog" aria-modal="true" aria-label="Pedido de contacto de demonstração" tabindex="-1" class="contact-modal"><button class="close" onclick={() => contact = false} aria-label="Fechar">×</button><p class="eyebrow">VAMOS CONVERSAR</p>{#if sent}<h2>Até à próxima<br/><em>conversa.</em></h2><p>Esta é uma demonstração: o pedido não foi enviado e os dados não foram guardados.</p><button class="button" onclick={() => contact = false}>Continuar a descobrir ↗</button>{:else}<h2>O primeiro passo<br/><em>é simples.</em></h2><p>Formulário de demonstração. Nenhuma mensagem será enviada.</p><form onsubmit={(e) => { e.preventDefault(); sent = true; }}><label>O seu nome<input required autocomplete="name" placeholder="Como se chama?"/></label><label>Email<input required type="email" autocomplete="email" placeholder="nome@exemplo.pt"/></label><label>O que procura?<textarea rows="3" value={car ? `Gostava de conhecer o ${car.brand} ${car.model}.` : ''} placeholder="Conte-nos um pouco dos seus planos."/></label><button class="button" type="submit">Experimentar pedido ↗</button></form>{/if}</section></div>{/if}
  {#if gallery && car}<div class="modal-backdrop gallery" role="dialog" aria-modal="true" aria-label="Fotografia ampliada" tabindex="-1"><button class="close" onclick={() => gallery = false} aria-label="Fechar fotografia">×</button><img src={photo(car.image, 2400)} alt={`${car.brand} ${car.model} — imagem ilustrativa ampliada`}/><p>Fotografia ilustrativa · {car.brand} {car.model}</p></div>{/if}
</div>

